<?php
require_login();$title='Noticeboard';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$titleN=post('title');$content=post('content');$expiry=post('expiry_date')?:null;$id=(int)($_POST['id']??0);if(!$titleN||!$content){flash('error','Title and content are required.');redirect('notices.php');}if($id){$s=$pdo->prepare("UPDATE notices SET title=?,content=?,expiry_date=? WHERE id=?");$s->execute([$titleN,$content,$expiry,$id]);}else{$s=$pdo->prepare("INSERT INTO notices(title,content,expiry_date,created_by) VALUES(?,?,?,?)");$s->execute([$titleN,$content,$expiry,auth()['id']]);}flash('success','Notice saved.');redirect('notices.php');}
if(isset($_GET['delete']) && auth()['role']==='admin'){$s=$pdo->prepare("DELETE FROM notices WHERE id=?");$s->execute([(int)$_GET['delete']]);flash('success','Notice deleted.');redirect('notices.php');}
$rows=$pdo->query("SELECT n.*,u.full_name creator FROM notices n JOIN users u ON u.id=n.created_by WHERE n.expiry_date IS NULL OR n.expiry_date>=CURDATE() ORDER BY n.created_at DESC")->fetchAll();require 'header.php';?>
<h1>Noticeboard</h1><div class="panel"><h2>Post Notice</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="formgrid"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Expiry date</label><input type="date" name="expiry_date"></div><div class="field full"><label>Content</label><textarea name="content" required></textarea></div></div><br><button class="btn">Publish Notice</button></form></div><br>
<?php foreach($rows as $r):?><div class="panel notice"><h2><?=e($r['title'])?></h2><p><?=nl2br(e($r['content']))?></p><div class="small muted2">Posted by <?=e($r['creator'])?> · Expires <?=e($r['expiry_date']??'No expiry')?></div><?php if(auth()['role']==='admin'):?><br><a class="btn danger" onclick="return confirm('Delete this notice?')" href="?delete=<?=$r['id']?>">Delete</a><?php endif;?></div><?php endforeach;?>
<?php require 'footer.php';?>
